-- 시험용 DB: 운영 DB(public 스키마)의 표·제약·인덱스 구조 복제 (데이터 없음). 2026-10-21 읽기 전용으로 추출.
-- 운영 구조가 바뀌면 이 파일도 갱신할 것(db/README.md 참고). Supabase 권한(RLS)·역할은 흉내만 냄.
create schema if not exists auth;
create table if not exists auth.users (id uuid primary key default gen_random_uuid(), email text);
create or replace function auth.uid() returns uuid language sql stable as $$
  select coalesce(
    nullif(current_setting('request.jwt.claim.sub', true), ''),
    (nullif(current_setting('request.jwt.claims', true), '')::jsonb ->> 'sub')
  )::uuid
$$;
-- 시험 편의: 운영의 anon/authenticated 역할 흉내(권한 시험은 하지 않음)
do $$ begin
  if not exists (select 1 from pg_roles where rolname='authenticated') then create role authenticated; end if;
  if not exists (select 1 from pg_roles where rolname='anon') then create role anon; end if;
end $$;

create sequence if not exists public.estimate_history_id_seq;

create table public.app_settings (key text not null, value jsonb not null, updated_at timestamptz default now());
create table public.customer_history (id bigint generated by default as identity not null, customer_id bigint not null, snapshot jsonb not null, changed_at timestamptz default now() not null, change_type text not null);
create table public.customers (
  id bigint generated by default as identity not null,
  created_at timestamptz default now() not null,
  client_name text, phone text, addr text, space text,
  price bigint default 0, performance_revenue bigint default 0,
  staff_name text default '선혜', stage text default '상담', date text, memo text,
  visit_count integer default 1, measure_date text, install_date text,
  deposit_amount numeric default 0, deposit_date text, deposit_method text, deposit_receipt boolean default false,
  balance_amount numeric default 0, balance_date text, balance_method text, balance_receipt boolean default false,
  is_archived boolean default false, order_status jsonb default '{}'::jsonb, branch text default '반포점',
  updated_at timestamptz default now(), lead_parked boolean default false, confirm_date text, payment_link text,
  measure_date_tbd boolean default false, install_date_tbd boolean default false, addr_detail text
);
create table public.estimates (
  id uuid default gen_random_uuid() not null,
  customer_name text not null, phone text, space text, product text,
  price numeric default 0, performance_revenue numeric default 0,
  staff_name text default '마스터', date text, memo text,
  created_at timestamp default now(), estimate_status text default 'ga', is_archived boolean default false,
  confirmed_at timestamptz, branch text default '반포점', client_id bigint, updated_at timestamptz default now(),
  line_items jsonb default '[]'::jsonb, as_install_date date, as_type text, as_symptom text, as_photo_memo text, as_fee_type text,
  client_idempotency_key text, cust_type text default 'new', region text,
  applied_discounts jsonb default '[]'::jsonb, price_breakdown jsonb, contract_status text default 'pending',
  install_date text, measure_date_tbd boolean default false, install_date_tbd boolean default false,
  installer_name text, installer_phone text,
  deposit_amount numeric, deposit_date text, deposit_method text, deposit_receipt boolean,
  balance_amount numeric, balance_date text, balance_method text, balance_receipt boolean
);
create table public.estimate_extra_payments (
  id uuid default gen_random_uuid() not null, estimate_id uuid not null, client_id bigint,
  amount numeric not null, paid_date text not null, method text default '' not null, receipt boolean default false not null,
  memo text, request_id uuid, created_by uuid default auth.uid(), created_at timestamptz default now() not null
);
create table public.estimate_history (
  id bigint default nextval('estimate_history_id_seq') not null, estimate_id uuid not null, snapshot jsonb not null,
  changed_at timestamptz default now() not null, change_type text not null
);
create table public.integrity_acks (ack_key text not null, code text not null, customer_id bigint, client_name text, note text, acked_by uuid default auth.uid() not null, acked_by_name text, acked_at timestamptz default now() not null);
create table public.integrity_daily_log (id bigint generated by default as identity not null, run_at timestamptz default now() not null, total_count integer not null, warn_count integer not null, by_code jsonb default '{}'::jsonb not null);
create table public.monthly_close (month text not null, revenue numeric default 0 not null, perf_revenue numeric default 0 not null, contract_count integer default 0 not null, by_staff jsonb default '{}'::jsonb not null, note text, closed_at timestamptz default now() not null, closed_by uuid default auth.uid());
create table public.payment_ledger (id bigint generated by default as identity not null, customer_id bigint not null, estimate_id uuid, staff_name text, kind text not null, amount numeric not null, paid_at date not null, date_estimated boolean default false not null, method text, memo text, source text default 'manual' not null, created_at timestamptz default now() not null, created_by uuid default auth.uid());
create table public.payment_refunds (
  id uuid default gen_random_uuid() not null, entry_type text default 'refund' not null, reverses_id uuid, estimate_id uuid not null,
  client_id bigint, customer_name text, staff_name text, slot text not null, amount numeric not null, paid_date text not null,
  pay_method text, refund_date text not null, reason text not null, request_id uuid, created_by uuid default auth.uid(), created_at timestamptz default now() not null
);
create table public.save_receipts (id bigint generated by default as identity not null, created_at timestamptz default now() not null, kind text not null, outcome text, customer_name text, estimate_id text, app_version text, user_email text, device text, detail jsonb default '{}'::jsonb not null);
create table public.staff_profiles (id uuid not null, display_name text not null, role text not null, created_at timestamptz default now());

-- 제약
alter table public.app_settings add constraint app_settings_pkey primary key (key);
alter table public.customer_history add constraint customer_history_pkey primary key (id);
alter table public.customers add constraint customers_pkey primary key (id);
alter table public.customers add constraint customers_amounts_nonneg_chk check (((coalesce(price, (0)::bigint) >= 0) and (coalesce(deposit_amount, (0)::numeric) >= (0)::numeric) and (coalesce(balance_amount, (0)::numeric) >= (0)::numeric) and (coalesce(performance_revenue, (0)::bigint) >= 0)));
alter table public.customers add constraint customers_dates_iso_chk check ((((date is null) or (date = '') or (date ~ '^\d{4}-\d{2}-\d{2}$')) and ((confirm_date is null) or (confirm_date = '') or (confirm_date ~ '^\d{4}-\d{2}-\d{2}$')) and ((install_date is null) or (install_date = '') or (install_date ~ '^\d{4}-\d{2}-\d{2}$')) and ((measure_date is null) or (measure_date = '') or (measure_date ~ '^\d{4}-\d{2}-\d{2}$')) and ((deposit_date is null) or (deposit_date = '') or (deposit_date ~ '^\d{4}-\d{2}-\d{2}$')) and ((balance_date is null) or (balance_date = '') or (balance_date ~ '^\d{4}-\d{2}-\d{2}$'))));
alter table public.customers add constraint customers_name_not_empty check (((client_name is not null) and (client_name <> '')));
alter table public.customers add constraint customers_stage_chk check ((stage = any (array['방문예약','상담','가견적','선금결제','실측준비중','확정견적','잔금결제','시공준비중','시공완료'])));
alter table public.estimates add constraint estimates_pkey primary key (id);
alter table public.estimates add constraint estimates_amounts_nonneg_chk check (((coalesce(price, (0)::numeric) >= (0)::numeric) and (coalesce(deposit_amount, (0)::numeric) >= (0)::numeric) and (coalesce(balance_amount, (0)::numeric) >= (0)::numeric) and (coalesce(performance_revenue, (0)::numeric) >= (0)::numeric)));
alter table public.estimates add constraint estimates_client_id_fkey foreign key (client_id) references public.customers(id);
alter table public.estimates add constraint estimates_dates_iso_chk check ((((date is null) or (date = '') or (date ~ '^\d{4}-\d{2}-\d{2}$')) and ((install_date is null) or (install_date = '') or (install_date ~ '^\d{4}-\d{2}-\d{2}$')) and ((deposit_date is null) or (deposit_date = '') or (deposit_date ~ '^\d{4}-\d{2}-\d{2}$')) and ((balance_date is null) or (balance_date = '') or (balance_date ~ '^\d{4}-\d{2}-\d{2}$'))));
alter table public.estimate_extra_payments add constraint estimate_extra_payments_pkey primary key (id);
alter table public.estimate_extra_payments add constraint estimate_extra_payments_amount_check check ((amount > 0));
alter table public.estimate_extra_payments add constraint estimate_extra_payments_estimate_id_fkey foreign key (estimate_id) references public.estimates(id) on delete cascade;
alter table public.estimate_extra_payments add constraint estimate_extra_payments_paid_date_check check ((paid_date ~ '^\d{4}-\d{2}-\d{2}$'));
alter table public.estimate_extra_payments add constraint estimate_extra_payments_request_id_key unique (request_id);
alter table public.estimate_history add constraint estimate_history_pkey primary key (id);
alter table public.integrity_acks add constraint integrity_acks_pkey primary key (ack_key);
alter table public.integrity_daily_log add constraint integrity_daily_log_pkey primary key (id);
alter table public.monthly_close add constraint monthly_close_pkey primary key (month);
alter table public.monthly_close add constraint monthly_close_month_check check ((month ~ '^[0-9]{4}-(0[1-9]|1[0-2])$'));
alter table public.payment_ledger add constraint payment_ledger_pkey primary key (id);
alter table public.payment_ledger add constraint payment_ledger_amount_check check ((amount <> 0));
alter table public.payment_ledger add constraint payment_ledger_check check ((((kind = '입금') and (amount > 0)) or ((kind = '환불') and (amount < 0)) or (kind = '조정')));
alter table public.payment_ledger add constraint payment_ledger_customer_id_fkey foreign key (customer_id) references public.customers(id) on delete cascade;
alter table public.payment_ledger add constraint payment_ledger_kind_check check ((kind = any (array['입금','환불','조정'])));
alter table public.payment_refunds add constraint payment_refunds_pkey primary key (id);
alter table public.payment_refunds add constraint payment_refunds_amount_check check ((amount > 0));
alter table public.payment_refunds add constraint payment_refunds_check check (((refund_date >= paid_date) or (entry_type = 'reversal')));
alter table public.payment_refunds add constraint payment_refunds_entry_type_check check ((entry_type = any (array['refund','reversal'])));
alter table public.payment_refunds add constraint payment_refunds_paid_date_check check ((paid_date ~ '^\d{4}-\d{2}-\d{2}$'));
alter table public.payment_refunds add constraint payment_refunds_reason_check check ((length(btrim(reason)) > 0));
alter table public.payment_refunds add constraint payment_refunds_refund_date_check check ((refund_date ~ '^\d{4}-\d{2}-\d{2}$'));
alter table public.payment_refunds add constraint payment_refunds_request_id_key unique (request_id);
alter table public.payment_refunds add constraint payment_refunds_reverses_id_fkey foreign key (reverses_id) references public.payment_refunds(id);
alter table public.payment_refunds add constraint payment_refunds_reverses_id_key unique (reverses_id);
alter table public.payment_refunds add constraint payment_refunds_slot_check check ((slot = any (array['deposit','balance'])));
alter table public.save_receipts add constraint save_receipts_pkey primary key (id);
alter table public.staff_profiles add constraint staff_profiles_pkey primary key (id);
alter table public.staff_profiles add constraint staff_profiles_id_fkey foreign key (id) references auth.users(id) on delete cascade;
alter table public.staff_profiles add constraint staff_profiles_role_check check ((role = any (array['master','staff'])));

-- 인덱스
create index idx_customers_client_name on public.customers using btree (client_name);
create index idx_customers_created_at on public.customers using btree (created_at desc);
create index idx_customers_stage on public.customers using btree (stage);
create index estimate_extra_payments_client_idx on public.estimate_extra_payments using btree (client_id);
create index estimate_extra_payments_estimate_idx on public.estimate_extra_payments using btree (estimate_id);
create index idx_estimate_history_estimate_id on public.estimate_history using btree (estimate_id, changed_at desc);
create unique index estimates_idempotency_key_uniq on public.estimates using btree (client_idempotency_key) where (client_idempotency_key is not null);
create index idx_estimates_client_id on public.estimates using btree (client_id);
create index idx_estimates_created_at on public.estimates using btree (created_at desc);
create index idx_estimates_customer_name on public.estimates using btree (customer_name);
create index payment_ledger_customer_idx on public.payment_ledger using btree (customer_id);
create index payment_ledger_paid_at_idx on public.payment_ledger using btree (paid_at);
